    def confirmationMesaage(self, Form):
        no = self.lineEdit_tank_number.text()
        vol = self.lineEdit_tank_volume.text()
        print(no, vol)

        if no != "" and vol != "":

            # checking
            try:
                data = connect_to_database("operational data/tank.db", "tank_basic_table")
                all_tanks = []
                for tank in data:
                    all_tanks.append(tank[1][5:])
                
                print(all_tanks)
               

                if no in all_tanks:
                    self.lbl_show_status.setText("ইতোমধ্যে নিবন্ধিত হয়েছে")
                    self.lbl_show_status.setStyleSheet("color: red;font: 63 17pt \"Baloo Da 2 SemiBold\" ")
                    self.lineEdit_tank_number.clear()

                    return
                else:
                    db().tank_basic_entry(no,vol) # connecting to db.

            except:
                print("Database is not connected or created")
                return 

            self.lineEdit_tank_number.clear()
            self.lineEdit_tank_volume.clear()

            self.lbl_show_status.setText("নিবন্ধন সম্পন্ন হয়েছে")
            self.lbl_show_status.setStyleSheet("color: green;font: 63 17pt \"Baloo Da 2 SemiBold\" ")
           
                        
        else:
            self.lbl_show_status.setText("কোন ঘর ফাঁকা রাখা যাবেন না। সঠিক ভাবে পূরণ করুন।")
            self.lbl_show_status.setStyleSheet("color: red ;font: 63 17pt \"Baloo Da 2 SemiBold\" ")


        

